after(async () => { await implementation; await rm(temporary, { recursive: true, force: true }); });
async function collections(expression) {
  return (await Promise.all((await readdir(path.join(site, 'data')))
    .filter(name => expression.test(name)).map(name => json('data/' + name)))).flat();
}
function walk(flow, item, choices) {
  const result = flow.walkFromRoot(choices, item.domain);
  assert.equal(result.consumed, choices.length, `${item.id}/${choices.join('/')}: every answer consumed`);
  return result;
}
function enterRoutes(flow, state) {
  for (let limit = 0; flow.evaluateState(state).current.type === 'route'; ++limit) {
    assert(limit < 100, 'route entry terminates');
    state = flow.enterFlowRoute(state);
  }
  return state;
}
function replay(flow, item, choices) {
  let state = flow.initialState(item.domain);
  for (const answer of choices) state = flow.answerState(enterRoutes(flow, state), answer);
  return enterRoutes(flow, state);
}
const weight = state => state.answers.length + (state.trail ?? [])
  .reduce((sum, context) => sum + context.answers.length + 1, 0);
function checkSvg(flow, graph) {
  const svg = flow.renderFlowSvg(graph);
  let edges = 0;
  for (const node of graph.nodes) {
    assert(svg.includes(`data-node="${node.id}"`), `${graph.id}/${node.id}: visible node`);
    if (node.type === 'question') for (const option of flow.getNodeOptions(node)) {
      ++edges;
      assert(svg.includes(`data-edge="${node.id}:${option.id}:${node.answers[option.id]}"`));
      assert(svg.includes(`<title>${xml(option.label)}</title>`), 'full answer label is readable');
    }
    if (node.type === 'result') for (const id of node.techniques ?? [])
      assert(svg.includes(`href="/flowchartcp/techniques/${id}/"`), 'result href opens the reusable article');
  }
  assert.equal((svg.match(/class="flow-edge /g) ?? []).length, edges);
  return svg;
}

// Independent raw-JSON replay. This fixed projection includes complete old
// terminal nodes, every step target, question title and selected answer label.
function rawWalk(graphs, record) {
  const byId = new Map(graphs.map(graph => [graph.id, graph]));
  const options = node => node.options ?? Object.keys(node.answers ?? {}).map(id => ({ id,
    label: { yes: 'はい', no: 'いいえ', unknown: 'わからない' }[id] ?? id }));
  let graph = byId.get(record.entryGraphId ?? 'ranges'); assert(graph);
  let node = graph.nodes.find(node => node.id === graph.root), consumed = 0;
  const steps = [], labels = [];
  for (let limit = 0; limit < 2000; ++limit) {
    assert(node);
    if (node.type === 'route') {
      graph = byId.get(node.graph); assert(graph);
      node = graph.nodes.find(node => node.id === graph.root); continue;
    }
    if (node.type !== 'question' || consumed === record.choices.length) {
      assert.equal(consumed, record.choices.length);
      return { graph: graph.id, node: node.id, type: node.type, current: node, steps, labels };
    }
    const answer = record.choices[consumed++]; assert(Object.hasOwn(node.answers, answer));
    const target = node.answers[answer];
    steps.push({ graph: graph.id, node: node.id, answer, target });
    labels.push({ graph: graph.id, node: node.id, title: node.title, answer,
      label: options(node).find(option => option.id === answer)?.label });
    node = graph.nodes.find(node => node.id === target);
  }
  assert.fail('raw route replay did not terminate');
}

