test('both feature routes require all three applicability checks without changing the four-option grid root', async () => {
  const { flow } = await implementation;
  assert.deepEqual(flow.validateGraphs(), []);
  assert.equal(flow.entryGraphs.length, 15);
  assert.equal(digest(flow.getGraph('grid-arrangements')), frozen.gridEntryHash,
    'the entire preexisting grid entrance, including its four choices, stays fixed');
  assert.deepEqual(flow.getNodeOptions(flow.getNode(flow.getGraph('grid-arrangements'), 'goal')).map(option => option.id),
    ['pairing-cover', 'movement-cycles', 'color-numbers', 'unknown']);
  for (const item of tasks) {
    const category = walk(flow, item, item.prefix.slice(0, -1));
    const option = flow.getNodeOptions(category.current).find(option => option.id === item.prefix.at(-1));
    assert(option);
    assert.doesNotMatch(option.label, /ICPC|Replicate|Catch the Plane|wf201[78]_/i);
    for (let at = 0; at < item.guards.length; ++at) {
      const value = walk(flow, item, [...item.prefix, ...Array(at).fill('yes')]);
      assert.equal(value.graph.id, item.graph); assert.notEqual(value.graph.entry, true);
      assert.equal(value.current.type, 'question'); assert.equal(value.current.id, item.guards[at]);
      assert(ids.every(id => !candidates(value).includes(id)));
      assert.deepEqual(flow.getNodeOptions(value.current).map(option => option.id).sort(), ['no', 'unknown', 'yes']);
    }
    const result = walk(flow, item, [...item.prefix, 'yes', 'yes', 'yes']);
    assert.equal(result.current.type, 'result'); assert.deepEqual(candidates(result), [item.id]);
    for (const term of item.terms) assert.match(JSON.stringify(result.graph), term);
    assert.equal(flow.getFlowDomainId(flow.initialState(item.graph)), item.domain);
  }
});

test('no and unknown at each of the six guards go to condition-check', async () => {
  const { flow } = await implementation;
  for (const item of tasks) for (let at = 0; at < item.guards.length; ++at)
    for (const answer of ['no', 'unknown']) {
      const result = walk(flow, item, [...item.prefix, ...Array(at).fill('yes'), answer]);
      assert.equal(result.graph.id, 'condition-check', `${item.id}/${item.guards[at]}/${answer}`);
      assert.equal(result.current.type, 'question');
      assert(ids.every(id => !candidates(result).includes(id)));
    }
});

test('question and diagram displays expose complete labels and reusable-article links', async () => {
  const { flow } = await implementation;
  const html = flow.renderFlowHtml('/flowchartcp/');
  assert(html.includes('data-view="questions"')); assert(html.includes('data-view="diagram"'));
  for (const item of tasks) {
    const graph = flow.getGraph(item.graph); checkSvg(flow, graph);
    assert(html.includes(`data-graph-panel="${item.graph}"`));
    for (const node of graph.nodes) {
      assert(html.includes(`id="flow-text-${item.graph}-${node.id}"`));
      assert(html.includes(xml(node.title)));
      if (node.type === 'question') for (const option of flow.getNodeOptions(node)) {
        assert(html.includes(xml(option.label)));
        assert(html.includes(`#flow-text-${item.graph}-${node.answers[option.id]}`));
      }
    }
    assert(html.includes(`/flowchartcp/techniques/${item.id}/`));
  }
});

test('shared URLs, path highlights and finite Back preserve both complete feature histories', async () => {
  const { flow, viewer } = await implementation;
  const diagrams = new Map();
  for (const item of tasks) {
    const histories = [[...item.prefix, 'yes', 'yes', 'yes']];
    for (let at = 0; at < item.guards.length; ++at) for (const answer of ['no', 'unknown'])
      histories.push([...item.prefix, ...Array(at).fill('yes'), answer]);
    for (const choices of histories) {
      let state = replay(flow, item, choices);
      assert.deepEqual(flow.evaluateState(state).current, walk(flow, item, choices).current);
      for (let limit = weight(state) + 1; ; --limit) {
        assert(limit > 0, 'Back terminates');
        assert.equal(flow.getFlowDomainId(state), item.domain);
        assert.deepEqual(flow.sanitizeState(state), state);
        const evaluation = flow.evaluateState(state);
        if (!diagrams.has(state.graph)) diagrams.set(state.graph, checkSvg(flow, evaluation.graph));
        const svg = diagrams.get(state.graph);
        assert(svg.includes(`data-node="${evaluation.current.id}"`));
        for (const node of evaluation.path) assert(svg.includes(`data-node="${node.id}"`));
        for (const edge of evaluation.edges) assert(svg.includes(`data-edge="${edge.from}:${edge.answer}:${edge.to}"`));
        const hash = flow.serializeFlowHash(state);
        assert.deepEqual(flow.parseFlowHash(hash), state);
        assert.deepEqual(viewer.diagramState(state.graph, hash), state);
        const url = new URL(viewer.diagramViewerUrl(state.graph, '/flowchartcp/', state), 'https://flowchartcp.test');
        assert.equal(url.pathname, `/flowchartcp/diagrams/${state.graph}/`); assert.equal(url.hash, hash);
        assert.deepEqual(viewer.diagramState(state.graph, url.hash), state);
        if (!weight(state)) break;
        const previous = flow.backFlowState(state); assert(weight(previous) < weight(state)); state = previous;
      }
      assert.deepEqual(state, flow.initialState(item.domain)); assert.deepEqual(flow.backFlowState(state), state);
    }
  }
});

test('each article, metadata, independent reference, feature and recorded canonical walk agrees', async () => {
  const { flow } = await implementation;
  const [metadata, references, walks] = await Promise.all([
    collections(/^techniques-.*\.json$/), collections(/^references-.*\.json$/), json('data/problem-walks.json'),
  ]);
  for (const item of tasks) {
    const techniques = metadata.filter(row => row.id === item.id); assert.equal(techniques.length, 1);
    const technique = techniques[0]; assert.equal(technique.kind, 'technique'); assert.equal(technique.status, 'reviewed');
    assert(technique.aliases.some(alias => /[A-Za-z]/.test(alias)));
    assert(technique.sources.includes(item.statement)); assert(technique.sources.includes(item.sketch));
    const article = await readFile(path.join(site, 'src/content/docs/techniques', item.id + '.mdx'), 'utf8');
    assert(new RegExp(`^techniqueId: ["']?${item.id}["']?\\s*$`, 'm').test(article));
    assert.deepEqual([...article.matchAll(/^## (.+)$/gm)].map(match => match[1]),
      ['使う場面', '考え方', '適用条件', 'なぜ正しいか', '計算量', '実装', '関連する手法', '参考資料']);
    assert.equal((article.match(/^```cpp\s*$/gm) ?? []).length, 1);
    assert(!/<(?:details|summary)\b/i.test(article)); assert.match(article, item.api);
    assert(article.includes(`techniqueId="${item.id}"`));
    for (const source of technique.sources) assert(article.includes(source));
    const refs = references.filter(row => matches(row, item) && row.techniqueId === item.id); assert.equal(refs.length, 1);
    const reference = refs[0]; assert.equal(reference.url, item.statement); assert.equal(reference.editorialUrl, item.sketch);
    assert.equal(reference.verification, 'independent-analysis'); assert.equal(reference.difficulty, null);
    assert(reference.evidence.trim().length > 0);
    assert.doesNotMatch(reference.evidence, /checker|コンパイル|乱択|ASan|UBSan/);
    assert.match(reference.verificationNotes, /unofficial|非公式/); assert.match(reference.verificationNotes, item.checkerCount);
    const features = (await json(item.featureFile)).filter(row => matches(row, item)); assert.equal(features.length, 1);
    const feature = features[0]; assert.deepEqual(feature.techniqueIds, [item.id]);
    assert.equal(feature.url, item.statement); assert.equal(feature.evidenceUrl, item.sketch);
    assert.equal(feature.verification, 'independent-analysis'); assert.equal(feature.reviewStatus, 'verified');
    assert.equal(feature.cutoff, '2026-10-14'); assert.equal(feature.publicationDateStatus, 'contest-before-cutoff');
    assert(feature.features.length >= 2);
    const examples = walks.filter(row => matches(row, item) && row.expectedTechniqueIds.includes(item.id)); assert.equal(examples.length, 1);
    const record = examples[0]; assert.equal(record.entryGraphId, item.domain);
    assert.deepEqual(record.choices, [...item.prefix, 'yes', 'yes', 'yes']);
    assert.deepEqual(record.expectedTechniqueIds, [item.id]); assert.equal(record.statementUrl, item.statement);
    assert.equal(record.evidenceUrl, item.sketch); assert.equal(record.verificationKind, 'independent-analysis');
    assert.equal(record.reviewStatus, 'verified'); assert.deepEqual(record.features, feature.features);
    const result = walk(flow, item, record.choices); assert.deepEqual(candidates(result), [item.id]);
    assert.deepEqual(result.steps.map(({ graph, node, answer }) => ({ graph, node, answer })), record.steps);
  }
});

test('original audit headers and initial research stay fixed, with later resolutions and honest source dates', async () => {
  const [references, walks, plan] = await Promise.all([
    collections(/^references-.*\.json$/), json('data/problem-walks.json'), json('data/coverage-plan.json'),
  ]);
  for (const item of tasks) {
    const audit = await json(`data/corpus-audits/icpc-${item.year}-world-finals.json`);
    const { records, ...header } = audit;
    assert.equal(digest(header), frozen.audits[item.year].headerHash, 'initial corpus selection/snapshot/counts remain unchanged');
    assert.equal(digest(records.map(({ resolution, ...initial }) => initial)), frozen.audits[item.year].initialRecordsHash,
      'all initial classifications, features, routes and missing-technique findings remain unchanged');
    const original = records.find(row => matches(row, item)); assert(original);
    assert.equal(original.classification, 'missing-technique'); assert.deepEqual(original.expectedTechniqueIds, []);
    assert.equal(original.difficulty, null); assert.equal(original.contest.year, item.year);
    assert.notEqual(original.technicalFindings.verification, 'official-editorial');
    assert.equal(original.resolution.status, 'verified'); assert.deepEqual(original.resolution.techniqueIds, [item.id]);
    assert(original.resolution.notes.trim().length > 0); assert.equal(isCorpusSolutionReviewed(original), true);
    const gap = plan.knownGaps.find(row => row.id === original.gap.id); assert(gap);
    assert.equal(gap.state, 'resolved'); assert.equal(gap.problemId, item.problemId); assert.deepEqual(gap.techniqueIds, [item.id]);
    const features = (await json(item.featureFile)).filter(row => matches(row, item));
    const related = [original, ...references.filter(row => matches(row, item) && row.techniqueId === item.id),
      ...features, ...walks.filter(row => matches(row, item) && row.expectedTechniqueIds.includes(item.id))];
    for (const row of related) {
      if (row.difficulty !== undefined) assert.equal(row.difficulty, null);
      if (row.publicationYear !== undefined) assert.equal(row.publicationYear, item.year);
      if (item.year === 2017) {
        for (const key of ['publicationDate', 'publicationMonth', 'sourceDate', 'sourceMonth', 'contestYearMonth', 'publicationYearMonth'])
          assert.equal(row[key], undefined, `unverified month/day is not invented in ${key}`);
        if (row.exactDateVerified !== undefined) assert.equal(row.exactDateVerified, false);
        if (row.contest) for (const key of ['date', 'yearMonth', 'month', 'day']) assert.equal(row.contest[key], undefined);
      } else {
        for (const key of ['publicationDate', 'sourceDate']) if (row[key] !== undefined) assert.equal(row[key], item.date);
        if (row.exactDateVerified !== undefined) assert.equal(row.exactDateVerified, true);
      }
    }
    if (item.year === 2017) assert.equal(features[0].publicationYear, 2017);
    else {
      assert.equal(original.contest.date, item.date); assert.equal(original.contest.exactDateVerified, true);
      assert.equal(features[0].publicationDate, item.date);
      const reference = related.find(row => row.techniqueId === item.id);
      assert.equal(reference.sourceDate ?? reference.publicationDate, item.date);
    }
  }
});

test('all frozen 501 complete records, exact terminals, steps and selected labels replay unchanged', async () => {
  const { flow } = await implementation;
  const [walks, graphs] = await Promise.all([json('data/problem-walks.json'), json('data/flows.json')]);
  const previous = walks.slice(0, frozen.recordCount); assert.equal(previous.length, 501);
  assert.equal(digest(previous), frozen.recordsHash);
  const observed = previous.map(record => rawWalk(graphs, record));
  assert.equal(digest(observed), frozen.walksHash);
  assert.equal(digest(observed.map(value => value.steps)), frozen.stepsHash);
  assert.equal(digest(observed.map(value => value.labels)), frozen.walkLabelsHash);
  previous.forEach((record, index) => {
    const actual = flow.walkFromRoot(record.choices, record.entryGraphId);
    assert.equal(actual.consumed, record.choices.length);
    assert.equal(actual.graph.id, observed[index].graph); assert.deepEqual(actual.current, observed[index].current);
    assert.deepEqual(actual.steps, observed[index].steps);
    assert.deepEqual(actual.steps.map(({ graph, node, answer }) => ({ graph, node, answer })), record.steps);
    assert.equal(actual.current.type, 'result');
    assert(record.expectedTechniqueIds.every(id => candidates(actual).includes(id)));
    const labels = actual.steps.map(step => {
      const node = flow.getNode(flow.getGraph(step.graph), step.node);
      return { graph: step.graph, node: step.node, title: node.title, answer: step.answer,
        label: flow.getAnswerLabel(node, step.answer) };
    });
    assert.deepEqual(labels, observed[index].labels);
  });
});

test('all frozen 972 result nodes and 1612 question titles and existing option labels remain fixed', async () => {
  const { flow } = await implementation;
  assert.equal(frozenKeys.terminalKeys.length, 972); assert.equal(frozenKeys.questionKeys.length, 1612);
  const terminals = frozenKeys.terminalKeys.map(([graph, node]) => ({ graph, node: flow.getNode(flow.getGraph(graph), node) }));
  assert.equal(digest(terminals), frozen.terminalsHash);
  const labels = frozenKeys.questionKeys.map(([graph, id, optionIds]) => {
    const node = flow.getNode(flow.getGraph(graph), id); assert.equal(node.type, 'question');
    const options = flow.getNodeOptions(node).filter(option => optionIds.includes(option.id));
    assert.equal(options.length, optionIds.length);
    return { graph, node: id, title: node.title, options };
  });
  assert.equal(digest(labels), frozen.questionsHash);
});
